export const parse = (s) => {
  if (String(s).trim() === '') throw new TypeError('empty input');
  return Number(s);
};

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { parse } from '../parse.js';

test('R1.1', () => assert.equal(parse('42'), 42));
test('R1.2', () => assert.throws(() => parse('  '), { name: 'TypeError', message: 'empty input' }));
